请对以下 case 进行三维加权评分。

=== case_id ===
Case-18-carpool-010

=== 用户原始指令 (query.txt) ===
整个拼车卡,显示一行拼到的人数,点导航去上车点,读日程,显示已拼成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个拼车卡,显示一行拼到的人数,点导航去上车点,读日程,显示已拼成",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": "22.543100",
            "longitude": "114.057900"
          },
          "trafficpe": "Drive"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "title": {
              "type": "string",
              "description": "拼车日程当前状态",
              "sampleValue": "已拼成"
            },
            "description": {
              "type": "string",
              "description": "拼车日程中的拼到人数展示文本",
              "sampleValue": "拼到3人"
            },
            "eventLocation": {
              "type": "string",
              "description": "拼车日程中的上车点短地址",
              "sampleValue": "上车点 北门"
            },
            "pickupLatitude": {
              "type": "string",
              "description": "日程上车点解析后的纬度，用于导航目的地",
              "sampleValue": "22.543100"
            },
            "pickupLongitude": {
              "type": "string",
              "description": "日程上车点解析后的经度，用于导航目的地",
              "sampleValue": "114.057900"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/person_3_fill.svg",
      "description": "三人组实心图标，适合表达拼车同行人数和已成团状态。"
    }
  ]
}

